import{_ as o,a0 as p,w as i,s as l,ao as d,I as s,x as e,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"命令列星期二——第六部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二——第六部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二——第六部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二——第六部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140731 Command Line Somedays--Part Six","title":"命令列星期二——第六部分","tag":"201408","desc":""},"relativePath":"201408/20140731 Command Line Somedays--Part Six.md","filePath":"[post].md"}'),m={name:"201408/20140731 Command Line Somedays--Part Six.md"};function x(h,t,u,f,g,C){const a=p("Link");return i(),l("div",null,[t[13]||(t[13]=d(`<h1 id="命令列星期二——第六部分" tabindex="-1">命令列星期二——第六部分 <a class="header-anchor" href="#命令列星期二——第六部分" aria-label="Permalink to “命令列星期二——第六部分”">​</a></h1><p>不管怎樣，讓我們繼續我們今天的日程吧：輸入/輸出重定向。</p><p>我們已經用過的大多數命令，都把他們的結果張貼到了終端顯示中。然而，我們也可以讓這些命令的顯示放進一個文件、設備中，或者作為其它命令的輸入，一切都在<strong>重定向</strong>。</p><h3 id="標準輸出" tabindex="-1">標準輸出 <a class="header-anchor" href="#標準輸出" aria-label="Permalink to “標準輸出”">​</a></h3><p>那麼，命令列程序主要是怎麼工作的呢？它們會將命令的結果丟給一個叫做標準輸出的設備，然後，標準輸出會將這些結果發送到你的顯示設備上，這樣你就可以暢快地閲讀這些信息了。然而，你也可以讓命令的結果顯示到一個文本文件中，像這樣，用“&gt;”字符（我的例子）：</p><pre><code>man zypper &gt; man.txt
</code></pre><p>這兒我所幹的是， 我想要獲得zypper的一個幫助頁。但是，我想要把它放到一個文本文件中去，因而我可以在我需要他們的時候（例如，在論壇、IRC尋求幫助時）很方便地讀取這些結果。所以，這個命令做的是，保存man zypper輸出結果到我的家目錄中的man.txt，這樣你可以看到，我可以用gedit來打開它：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Zaslonska-slika-2014-07-30-103144.png" alt=""></p><p>如果我重複了該命令，或者使用不同的命令重定向到了同名文件，那麼它就會被一次又一次地覆蓋。所以，在那種情況下，如果我想要把輸出結果重定向並附加到現存文件中，我唯一能做的事情就是下一次使用“&gt;&gt;”來替換“&gt;”。</p><h3 id="標準輸入" tabindex="-1">標準輸入 <a class="header-anchor" href="#標準輸入" aria-label="Permalink to “標準輸入”">​</a></h3><p>許多命令也可以接受來自稱之為標準輸入的設備的輸入。默認情況下，輸入來自鍵盤，然而也可以來自一個文件。要重定向它，使用跟前面相反的字符：‘<strong>&lt;</strong>’。</p><p>請看下面的例子：</p><pre><code>sort &lt; man.txt
</code></pre><h3 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to “管道”">​</a></h3><p>要想把多個命令連接到一起，你可以使用管道。管道所要做的是，將一個命令的標準輸出注入到另一個命令的標準輸入。肖茨先生的最愛：</p><pre><code>ls – l | less
</code></pre><p>通過使用‘| less’這個小把戲，你可以讓任何命令滾動輸出。 過濾器</p><h3 id="過濾器" tabindex="-1">過濾器 <a class="header-anchor" href="#過濾器" aria-label="Permalink to “過濾器”">​</a></h3><p>過濾器是管道中常用的程序。過濾器獲取標準輸入，對它進行操作，然後把結果發送到標準輸出。它們可以以一種相當強大的方式處理信息。這兒提供了一個程序列表，大多數都是用作過濾器的。它們可以用於執行、查詢，或者將幫助頁重定向到它們，然後再重定向到一個文件！</p><p>過濾器：sort, uniq, grep （我們發現這一個東西遍佈論壇，因此我建議大家深入研究一下）, fmt, pr, head, tail, tr, sed, awk。</p><h3 id="結束" tabindex="-1">結束 <a class="header-anchor" href="#結束" aria-label="Permalink to “結束”">​</a></h3><p>我們只剩下幾個課程來闡述CLI的基本用法了，到成熟期的時候，我希望大家都會對CLI興趣會增多一點了，也希望大家在蕭條期也進行一些探索！而在你們動手乾的時候，我希望你們…… <strong>玩得不亦樂乎！</strong></p><hr>`,23)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"https://news.opensuse.org/2014/07/30/command-line-somedays-part-six/"},{default:r(()=>[...t[0]||(t[0]=[e("https://news.opensuse.org/2014/07/30/command-line-somedays-part-six/",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=e("作者：",-1)),n(a,{href:"https://news.opensuse.org/author/holden87/"},{default:r(()=>[...t[2]||(t[2]=[e("Nenad Latinović",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),n(a,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),n(a,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const P=o(m,[["render",x]]);export{b as __pageData,P as default};
